<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Personal Expense Tracker</title>
<style>
    body {font-family: Arial, sans-serif; margin:20px; max-width:800px;}
    h1, h2 {margin-bottom:0.5em;}
    label {display:block;margin:0.3em 0;}
    input, select, button {padding:0.3em;font-size:1em;}
    #expenses-list {border-top:1px solid #ccc; margin-top:1em;}
    .expense {display:flex; justify-content:space-between; padding:0.5em 0; border-bottom:1px solid #eee;}
    .expense span {margin-right:1em;}
    .exp-del {background:#d33;color:#fff;border:none;padding:0.2em 0.5em;cursor:pointer;}
    #form-error {color:#c00;margin-top:0.5em;height:1.2em;}
    #total {font-weight:bold;}
    .cat-total {display:inline-block;margin-right:1em;}
    .hidden {display:none;}
    .controls {margin:0.5em 0;}
</style>
</head>
<body>
<h1>Personal Expense Tracker</h1>

<section id="entry-section">
    <h2>Add Expense</h2>
    <form id="expense-form">
        <label>Amount ($):
            <input type="number" step="0.01" id="amount" />
        </label>
        <label>Category:
            <select id="category">
                <option value="groceries">Groceries</option>
                <option value="transport">Transport</option>
                <option value="bills">Bills</option>
                <option value="fun">Fun</option>
            </select>
        </label>
        <label>Date:
            <input type="date" id="date" />
        </label>
        <label>Note (optional):
            <input type="text" id="note" />
        </label>
        <button type="submit" id="add-expense">Add Expense</button>
        <div id="form-error"></div>
    </form>
</section>

<section id="filters-section">
    <h2>Filters</h2>
    <div class="controls">
        <label>Category:
            <select id="filter-category">
                <option value="all">All</option>
                <option value="groceries">Groceries</option>
                <option value="transport">Transport</option>
                <option value="bills">Bills</option>
                <option value="fun">Fun</option>
            </select>
        </label>
        <label>From:
            <input type="date" id="filter-from" />
        </label>
        <label>To:
            <input type="date" id="filter-to" />
        </label>
    </div>
</section>

<section id="list-section">
    <h2>Expenses</h2>
    <div id="expenses-list"></div>
</section>

<section id="summary-section">
    <h2>Summary</h2>
    <p>Total: $<span id="total">0.00</span></p>
    <div id="category-totals">
        <span class="cat-total" data-cat="groceries">Groceries: $0.00</span>
        <span class="cat-total" data-cat="transport">Transport: $0.00</span>
        <span class="cat-total" data-cat="bills">Bills: $0.00</span>
        <span class="cat-total" data-cat="fun">Fun: $0.00</span>
    </div>
</section>

<script>
(() => {
    const STORAGE_KEY = 'expenses';
    const categories = ['groceries','transport','bills','fun'];

    // ----- Utility -----
    const $ = sel => document.querySelector(sel);
    const $$ = sel => Array.from(document.querySelectorAll(sel));

    // ----- Data handling -----
    function loadExpenses() {
        const json = localStorage.getItem(STORAGE_KEY);
        return json ? JSON.parse(json) : [];
    }

    function saveExpenses(arr) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(arr));
    }

    let expenses = loadExpenses(); // [{id, amount, category, date, note}]

    // ----- Rendering -----
    const listEl = $('#expenses-list');

    function createRow(exp) {
        const row = document.createElement('div');
        row.className = 'expense';
        row.dataset.id = exp.id;
        row.dataset.amount = exp.amount;
        row.dataset.category = exp.category;
        row.dataset.date = exp.date;

        const infoSpan = document.createElement('span');
        infoSpan.textContent = `$${Number(exp.amount).toFixed(2)} – ${exp.category} – ${exp.date}`;
        if (exp.note) {
            const noteSpan = document.createElement('span');
            noteSpan.style.fontStyle = 'italic';
            noteSpan.textContent = ` (${exp.note})`;
            infoSpan.appendChild(noteSpan);
        }
        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'exp-del';
        delBtn.textContent = '✕';

        row.appendChild(infoSpan);
        row.appendChild(delBtn);
        return row;
    }

    function renderAll() {
        listEl.innerHTML = '';
        // newest first (by id/timestamp)
        const sorted = [...expenses].sort((a,b)=> b.id - a.id);
        sorted.forEach(exp => listEl.appendChild(createRow(exp)));
        applyFilters();
    }

    // ----- Totals -----
    function updateTotals() {
        const visibleRows = $$('.expense').filter(r=> r.style.display !== 'none');
        let total = 0;
        const catMap = {};
        categories.forEach(c=> catMap[c]=0);

        visibleRows.forEach(row=>{
            const amt = Number(row.dataset.amount);
            total += amt;
            const cat = row.dataset.category;
            if (catMap.hasOwnProperty(cat)) catMap[cat] += amt;
        });

        $('#total').textContent = total.toFixed(2);
        $$('.cat-total').forEach(el=>{
            const cat = el.dataset.cat;
            el.textContent = `${capitalize(cat)}: $${catMap[cat].toFixed(2)}`;
        });
    }

    function capitalize(s){
        return s.charAt(0).toUpperCase()+s.slice(1);
    }

    // ----- Filtering -----
    function applyFilters(){
        const selCat = $('#filter-category').value;
        const from = $('#filter-from').value;
        const to   = $('#filter-to').value;

        $$('.expense').forEach(row=>{
            const cat = row.dataset.category;
            const date = row.dataset.date;
            let ok = true;
            if (selCat !== 'all' && cat !== selCat) ok = false;
            if (from && date < from) ok = false;
            if (to && date > to) ok = false;
            row.style.display = ok ? '' : 'none';
        });
        updateTotals();
    }

    // ----- Event Listeners -----
    // Form submission
    $('#expense-form').addEventListener('submit', e=>{
        e.preventDefault();
        const amountInput = $('#amount');
        const categorySelect = $('#category');
        const dateInput = $('#date');
        const noteInput = $('#note');
        const errDiv = $('#form-error');

        const amountVal = amountInput.value.trim();
        const dateVal = dateInput.value.trim();

        const amountNum = Number(amountVal);
        if (!amountVal || isNaN(amountNum) || amountNum<=0){
            errDiv.textContent = 'Please enter a positive amount.';
            return;
        }
        if (!dateVal){
            errDiv.textContent = 'Please select a date.';
            return;
        }
        // Passed validation
        errDiv.textContent = '';

        const newExp = {
            id: Date.now(),
            amount: amountNum.toFixed(2),
            category: categorySelect.value,
            date: dateVal,
            note: noteInput.value.trim()
        };
        expenses.unshift(newExp); // keep newest first in array
        saveExpenses(expenses);
        // Prepend new row
        listEl.insertBefore(createRow(newExp), listEl.firstChild);
        // Reset amount field
        amountInput.value = '';
        // Keep other fields unchanged (optional)
        applyFilters();
    });

    // Delete handling (event delegation)
    listEl.addEventListener('click', e=>{
        if (e.target.classList.contains('exp-del')){
            const row = e.target.closest('.expense');
            const id = Number(row.dataset.id);
            expenses = expenses.filter(exp=>exp.id!==id);
            saveExpenses(expenses);
            row.remove();
            applyFilters();
        }
    });

    // Filter controls
    $('#filter-category').addEventListener('change', applyFilters);
    $('#filter-from').addEventListener('change', applyFilters);
    $('#filter-to').addEventListener('change', applyFilters);

    // Initial render
    renderAll();
})();
</script>
</body>
</html>
